# ── UN Security Council Consolidated Sanctions List ──────────────────────────
# Loaded at module startup from the XML file. Parsed once and merged into
# the combined screening list alongside OFAC SDN entries.

def _load_un_sanctions() -> list:
    """
    Parse the UN Security Council Consolidated List XML and return
    a list of entries in the same format as OFAC SDN entries.
    1,009 entries: 737 individuals, 272 entities across 14 programmes
    (Al-Qaida, Taliban, DPRK, Iran, Iraq, Libya, DRC, Somalia, CAR, Sudan,
     Yemen, Haiti, South Sudan, GB).
    """
    import xml.etree.ElementTree as _ET
    import os as _os2

    _xml_path = _os2.path.join(_os2.path.dirname(_os2.path.abspath(__file__)), 'un_sanctions.xml')
    if not _os2.path.exists(_xml_path):
        print(f"[Sanctions] UN XML not found at {_xml_path}", flush=True)
        return []

    def _t(el, tag):
        f = el.find(tag)
        return (f.text or '').strip() if f is not None else ''

    def _multi(el, tag, sub):
        return [v for v in (
            (item.find(sub).text or '').strip()
            for item in el.findall(tag)
            if item.find(sub) is not None
        ) if v]

    def _aliases(el, alias_tag):
        names = []
        for a in el.findall(alias_tag):
            n = _t(a, 'ALIAS_NAME')
            if n: names.append(n)
        return names

    try:
        _tree = _ET.parse(_xml_path)
        _root = _tree.getroot()
    except Exception as _e:
        print(f"[Sanctions] Failed to parse UN XML: {_e}", flush=True)
        return []

    _entries = []
    _individuals_el = _root.find('INDIVIDUALS')
    _entities_el    = _root.find('ENTITIES')

    # Individuals
    for _ind in (_individuals_el.findall('INDIVIDUAL') if _individuals_el is not None else []):
        _parts = [_t(_ind, f) for f in ['FIRST_NAME','SECOND_NAME','THIRD_NAME','FOURTH_NAME']]
        _parts = [p for p in _parts if p]
        _name  = ' '.join(_parts).strip()
        if not _name: continue
        _nats  = _multi(_ind, 'NATIONALITY', 'VALUE')
        _dob   = ''
        for _dob_el in _ind.findall('INDIVIDUAL_DATE_OF_BIRTH'):
            _d = _t(_dob_el,'DATE') or _t(_dob_el,'YEAR') or _t(_dob_el,'FROM_YEAR')
            if _d: _dob = _d; break
        _prog = _t(_ind,'UN_LIST_TYPE')
        _interpol = _t(_ind,'HAS_INTERPOL_LINK') == 'YES'
        _entries.append({
            'id':       f"UN-{_t(_ind,'DATAID')}",
            'name':     _name,
            'type':     'individual',
            'program':  [f"UN-{_prog}"] if _prog else ['UN-List'],
            'aka':      _aliases(_ind, 'INDIVIDUAL_ALIAS'),
            'country':  _nats[0] if _nats else '',
            'dob':      _dob or None,
            'reason':   (_t(_ind,'COMMENTS1') or '')[:300],
            'date_added': _t(_ind,'LISTED_ON'),
            'reference':  _t(_ind,'REFERENCE_NUMBER'),
            'interpol':   _interpol,
            'source':     'UN Security Council',
            'score_threshold': 78,
        })

    # Entities
    for _ent in (_entities_el.findall('ENTITY') if _entities_el is not None else []):
        _name = _t(_ent,'FIRST_NAME').strip()
        if not _name: continue
        _country = ''
        for _addr in _ent.findall('ENTITY_ADDRESS'):
            _c = _t(_addr,'COUNTRY')
            if _c: _country = _c; break
        _prog = _t(_ent,'UN_LIST_TYPE')
        _entries.append({
            'id':       f"UN-{_t(_ent,'DATAID')}",
            'name':     _name,
            'type':     'entity',
            'program':  [f"UN-{_prog}"] if _prog else ['UN-List'],
            'aka':      _aliases(_ent, 'ENTITY_ALIAS'),
            'country':  _country,
            'dob':      None,
            'reason':   (_t(_ent,'COMMENTS1') or '')[:300],
            'date_added': _t(_ent,'LISTED_ON'),
            'reference':  _t(_ent,'REFERENCE_NUMBER'),
            'interpol':   False,
            'source':     'UN Security Council',
            'score_threshold': 78,
        })

    print(f"[Sanctions] UN list loaded: {len(_entries)} entries "
          f"({sum(1 for e in _entries if e['type']=="individual")} individuals, "
          f"{sum(1 for e in _entries if e['type']=="entity")} entities)", flush=True)
    return _entries

_UN_ENTRIES = _load_un_sanctions()

