# ── Fuzzy matching ────────────────────────────────────────────────────────────
# ── Levenshtein edit distance ─────────────────────────────────────────────────
def _levenshtein(s1: str, s2: str) -> int:
    s1, s2 = s1.lower().strip(), s2.lower().strip()
    if s1 == s2: return 0
    if len(s1) < len(s2): s1, s2 = s2, s1
    prev = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1):
        curr = [i + 1]
        for j, c2 in enumerate(s2):
            curr.append(min(prev[j+1]+1, curr[j]+1, prev[j]+(0 if c1==c2 else 1)))
        prev = curr
    return prev[-1]

# ── Transliteration map: Cyrillic romanisations and common variant spellings ───
# Handles: Iryna/Irina, y/i equivalence, -skaya/-skaia/-sky, ph/f, etc.
_TRANSLIT_MAP = {
    # Vowel variants (East Slavic name transliterations)
    "iryna": "irina", "irina": "iryna",
    "mykola": "nikolai", "nikolai": "mykola",
    "oleksiy": "aleksei", "aleksei": "oleksiy",
    "volodymyr": "vladimir", "vladimir": "volodymyr",
    "yuriy": "yuri", "yuri": "yuriy",
    "dmytro": "dmitri", "dmitri": "dmytro",
    "serhiy": "sergei", "sergei": "serhiy",
    "andriy": "andrei", "andrei": "andriy",
    "vasyl": "vasili", "vasili": "vasyl",
    "mykhailo": "mikhail", "mikhail": "mykhailo",
    "olena": "elena", "elena": "olena",
    "tetyana": "tatiana", "tatiana": "tetyana",
    "oksana": "oxana", "oxana": "oksana",
    # Surname suffix variants
    "skaya": "skaia", "skaia": "skaya",
    "skiy": "sky", "sky": "skiy",
    "nikov": "nikow", "nikow": "nikov",
}

# Common letter substitutions in transliteration
_CHAR_EQUIV = [
    ("y", "i"),  # Iryna vs Irina
    ("ie", "e"), ("ia", "ya"), ("iy", "y"),
    ("ph", "f"), ("kh", "h"), ("zh", "j"),
    ("ts", "c"), ("ch", "tch"), ("sh", "sch"),
    ("oe", "o"), ("ae", "a"), ("ue", "u"),
    ("ck", "k"), ("ks", "x"),
]

def _transliterate_normalize(name: str) -> list:
    """Return a list of transliteration variants of a name for broader matching."""
    base = name.lower().strip()
    variants = {base}
    # Apply transliteration word-level substitutions
    tokens = base.split()
    for i, tok in enumerate(tokens):
        if tok in _TRANSLIT_MAP:
            alt_tokens = tokens[:i] + [_TRANSLIT_MAP[tok]] + tokens[i+1:]
            variants.add(" ".join(alt_tokens))
    # Apply character-level substitutions
    for old_ch, new_ch in _CHAR_EQUIV:
        if old_ch in base:
            variants.add(base.replace(old_ch, new_ch))
        if new_ch in base:
            variants.add(base.replace(new_ch, old_ch))
    return list(variants)

# ── Soundex phonetic fingerprint ──────────────────────────────────────────────
def _soundex(name: str) -> str:
    """Generate Soundex code for phonetic matching of name variants."""
    name = name.upper().strip()
    if not name: return "0000"
    # Keep first letter, map others to digits
    codes = {"BFPV": "1", "CGJKQSXYZ": "2", "DT": "3",
             "L": "4", "MN": "5", "R": "6"}
    result = name[0]
    last_code = ""
    for ch in name[1:]:
        for letters, code in codes.items():
            if ch in letters:
                if code != last_code:
                    result += code
                    last_code = code
                break
        else:
            last_code = ""
        if len(result) == 4:
            break
    return result.ljust(4, "0")

# ── Initial/abbreviated name expansion ────────────────────────────────────────
def _expand_initials(name: str) -> list:
    """
    Handle abbreviated names like 'I. Krasilnikova' — generates candidate
    full-name patterns to match against. Returns list of (pattern, is_initial_match).
    'I. Krasilnikova' → surname='krasilnikova', initial='i'
    We then match any SDN entry whose surname matches AND first name starts with 'i'.
    """
    tokens = name.lower().split()
    initials = []
    words = []
    for tok in tokens:
        clean = tok.strip(".")
        if len(clean) == 1:
            initials.append(clean)
        elif len(tok) == 2 and tok[1] == ".":
            initials.append(tok[0])
        else:
            words.append(clean)
    return initials, words

def _names_initial_match(query_name: str, sdn_name: str) -> tuple:
    """
    Returns (score, reason) if query abbreviated name matches SDN full name.
    'I. Krasilnikova' vs 'Iryna Petrovna Krasilnikova' → (92, 'Initial I matches Iryna + surname match')
    """
    q_initials, q_words = _expand_initials(query_name)
    if not q_initials or not q_words:
        return 0, ""
    # Decompose SDN name into tokens
    sdn_tokens = sdn_name.lower().split()
    # Try to match each surname word from query against SDN
    surname_score = max(
        (_levenshtein(qw, st) == 0 and 100 or max(0, 100 - _levenshtein(qw, st) * 15))
        for qw in q_words for st in sdn_tokens
    ) if q_words and sdn_tokens else 0
    # Try to match initials against SDN first names
    initial_match = any(
        st.startswith(qi) for qi in q_initials for st in sdn_tokens
    )
    if surname_score >= 85 and initial_match:
        return 90, f"Initial(s) {','.join(q_initials).upper()}. match first name + surname match"
    elif surname_score >= 70 and initial_match:
        return 78, f"Partial: initial(s) + approx. surname match"
    return 0, ""

# ── Enhanced similarity ────────────────────────────────────────────────────────
def _similarity(a: str, b: str) -> tuple:
    """
    Enhanced similarity returning (score, method) tuple.
    Handles: exact, substring, token overlap, Levenshtein, phonetic, transliteration, initials.
    """
    a_orig, b_orig = a.lower().strip(), b.lower().strip()
    if not a_orig or not b_orig: return 0, "empty"
    if a_orig == b_orig: return 100, "exact_match"

    # Substring containment (e.g. "Harborline" in "Harborline Maritime LLC")
    if a_orig in b_orig or b_orig in a_orig:
        score = round(90 * min(len(a_orig), len(b_orig)) / max(len(a_orig), len(b_orig)))
        return score, "substring_match"

    # Initial/abbreviated name check
    init_score, init_reason = _names_initial_match(a_orig, b_orig)
    if not init_score:
        init_score, init_reason = _names_initial_match(b_orig, a_orig)
    if init_score > 0:
        return init_score, f"initial_expansion: {init_reason}"

    # Token overlap
    ta = [t for t in re.split(r'\W+', a_orig) if len(t) > 1]
    tb = [t for t in re.split(r'\W+', b_orig) if len(t) > 1]
    if ta and tb:
        overlap = len(set(ta) & set(tb)) / max(len(set(ta)), len(set(tb)))
        if overlap >= 0.6:
            return round(70 + overlap * 28), "token_overlap"
        elif overlap >= 0.4:
            return round(55 + overlap * 25), "partial_token_overlap"

    # Transliteration variants
    a_variants = _transliterate_normalize(a_orig)
    b_variants = _transliterate_normalize(b_orig)
    best_translit = 0
    for av in a_variants:
        for bv in b_variants:
            if av == bv: return 88, "transliteration_match"
            dist = _levenshtein(av, bv)
            mx = max(len(av), len(bv))
            if mx > 0:
                s = round((1 - dist / mx) * 100)
                if s > best_translit: best_translit = s
    if best_translit >= 82:
        return best_translit, "transliteration_variant"

    # Phonetic (Soundex) matching of individual tokens
    if ta and tb:
        phonetic_hits = sum(1 for t in ta if any(_soundex(t) == _soundex(u) for u in tb))
        if phonetic_hits > 0:
            phon_score = round(55 + (phonetic_hits / max(len(ta), len(tb))) * 30)
            if phon_score >= 65:
                return phon_score, f"phonetic_match ({phonetic_hits} token(s))"

    # Levenshtein fallback
    dist = _levenshtein(a_orig, b_orig)
    score = round(max(0, (1 - dist / max(len(a_orig), len(b_orig))) * 100))
    return score, "levenshtein"

def _normalize(name: str) -> str:
    name = name.lower().strip()
    name = re.sub(r'[,\.\-_&]', ' ', name)
    name = re.sub(r'\b(llc|ltd|inc|corp|co|group|holdings|international|'
                  r'services|finance|capital|trading|enterprise|enterprises|'
                  r'bank|banks|pjsc|ojsc|fze|sprl|gmbh|sa|as|bv|maritime|'
                  r'financial|management|consulting|partners|associates|limited)\b', '', name)
    name = re.sub(r'\s+', ' ', name).strip()
    return name





# Build the fast-lookup index over the complete combined list
_SDN_INDEX = {}
for _bi, _entry in enumerate(SDN_LIST):
    _all_names = [_entry["name"]] + _entry.get("aka", [])
    for _nm in _all_names:
        _nm_n = _normalize(_nm)
        _tokens = [_t for _t in _nm_n.split() if len(_t) >= 2]
        for _tok in _tokens:
            _key = _tok[:4].lower()
            if _key not in _SDN_INDEX:
                _SDN_INDEX[_key] = set()
            _SDN_INDEX[_key].add(_bi)

def _build_index():
    global _SDN_INDEX
    for i, entry in enumerate(SDN_LIST):
        all_names = [entry["name"]] + entry.get("aka", [])
        for nm in all_names:
            nm_n = _normalize(nm)
            tokens = [t for t in nm_n.split() if len(t) >= 2]
            for tok in tokens:
                key = tok[:4].lower()  # 4-char prefix
                if key not in _SDN_INDEX:
                    _SDN_INDEX[key] = set()
                _SDN_INDEX[key].add(i)



def screen_entity(name: str, country: str = None, entity_type: str = None) -> dict:
    """Screen an entity name against the full OFAC SDN list (17,007 entries)."""
    if not name or len(name.strip()) < 2:
        return {"status": "error", "message": "Name too short to screen"}

    norm_name = _normalize(name)
    
    # Fast candidate selection using token index
    query_tokens = [t for t in norm_name.split() if len(t) >= 2]
    candidate_indices: set = set()
    for tok in query_tokens:
        key = tok[:4].lower()
        candidate_indices |= _SDN_INDEX.get(key, set())
        # Also try 2-char and 3-char prefixes for short names
        if len(tok) >= 3:
            candidate_indices |= _SDN_INDEX.get(tok[:3], set())
        if len(tok) >= 2:
            candidate_indices |= _SDN_INDEX.get(tok[:2], set())
    
    # If no candidates found via index, fall back to checking all (name too short/unusual)
    if not candidate_indices:
        candidate_indices = set(range(len(SDN_LIST)))
    
    matches = []
    candidates = [SDN_LIST[i] for i in candidate_indices]

    for entry in candidates:
        best_score = 0
        best_match_on = "primary"
        best_method = "levenshtein"
        # Check primary name
        s, method = _similarity(norm_name, _normalize(entry["name"]))
        if s > best_score:
            best_score, best_match_on, best_method = s, f"primary name: {entry['name']}", method
        # Check all AKA variants — critical for catching abbreviated/transliterated names
        for aka in entry.get("aka", []):
            s, method = _similarity(norm_name, _normalize(aka))
            if s > best_score:
                best_score, best_match_on, best_method = s, f"AKA: {aka}", method
        # Also try matching the raw (un-normalised) query against AKAs
        raw_norm = name.lower().strip()
        for aka in entry.get("aka", []):
            s, method = _similarity(raw_norm, aka.lower().strip())
            if s > best_score:
                best_score, best_match_on, best_method = s, f"AKA (raw): {aka}", method
        # Country boost
        country_match = False
        if country and entry.get("country"):
            ec = entry["country"].lower()
            qc = country.lower()
            if qc in ec or ec in qc:
                country_match = True
                if best_score >= 60:
                    best_score = min(100, best_score + 8)
        if best_score >= 55:
            threshold = entry.get("score_threshold", 80)
            hit_type = ("CONFIRMED_HIT" if best_score >= threshold else
                        "POTENTIAL_MATCH" if best_score >= 70 else "WEAK_MATCH")
            # Build human-readable confidence explanation
            confidence_pct = best_score
            if best_method == "exact_match":
                explanation = f"Exact name match. Confidence: {confidence_pct}%."
            elif best_method == "initial_expansion":
                explanation = f"Abbreviated name matched via initial expansion ({best_match_on}). Confidence: {confidence_pct}%."
            elif best_method == "transliteration_match":
                explanation = f"Transliteration variant matched. Confidence: {confidence_pct}%."
            elif best_method == "transliteration_variant":
                explanation = f"Close transliteration variant. Confidence: {confidence_pct}%."
            elif best_method == "phonetic_match":
                explanation = f"Phonetic (Soundex) match detected. Confidence: {confidence_pct}%."
            elif best_method == "token_overlap":
                explanation = f"High token overlap with known alias. Confidence: {confidence_pct}%."
            else:
                explanation = f"Fuzzy name match ({best_method}). Confidence: {confidence_pct}%."
            matches.append({
                "sdn_id": entry["id"], "sdn_name": entry["name"],
                "match_score": best_score, "match_on": best_match_on,
                "match_method": best_method, "explanation": explanation,
                "hit_type": hit_type,
                "programs": entry.get("program", []),
                "country": entry.get("country",""), "entity_type": entry["type"],
                "reason": entry.get("reason",""), "date_added": entry.get("date_added",""),
                "country_match": country_match, "dob": entry.get("dob"),
                "beneficial_owner_note": entry.get("reason","") if "owned by" in entry.get("reason","").lower() else "",
            })

    matches.sort(key=lambda x: -x["match_score"])

    jurisdiction_hits = []
    if country:
        for jur_name, jur_info in HIGH_RISK_JURISDICTIONS.items():
            if country.lower() in jur_name.lower() or jur_name.lower() in country.lower():
                jurisdiction_hits.append({
                    "jurisdiction": jur_name, "risk_level": jur_info["risk"],
                    "programs": jur_info["programs"], "fatf_status": jur_info["fatf"],
                })

    confirmed = [m for m in matches if m["hit_type"] == "CONFIRMED_HIT"]
    potential  = [m for m in matches if m["hit_type"] == "POTENTIAL_MATCH"]

    if confirmed:           status, risk_level = "HIT", "critical"
    elif potential:         status, risk_level = "POTENTIAL_MATCH", "high"
    elif jurisdiction_hits and jurisdiction_hits[0]["risk_level"] == "critical":
                            status, risk_level = "JURISDICTION_RISK", "high"
    elif jurisdiction_hits: status, risk_level = "JURISDICTION_RISK", "elevated"
    elif matches:           status, risk_level = "WEAK_MATCH", "medium"
    else:                   status, risk_level = "CLEAR", "low"

    return {
        "query": name, "normalized_query": norm_name,
        "status": status, "risk_level": risk_level,
        "matches": matches[:5], "confirmed_hits": len(confirmed),
        "potential_matches": len(potential), "jurisdiction_hits": jurisdiction_hits,
        "screened_at": datetime.now().isoformat(),
        "list_version": f"OFAC-SDN Apr-2026 ({len(SDN_LIST):,} entries)",
        "total_checked": len(SDN_LIST),
        "action_required": status in ("HIT", "POTENTIAL_MATCH"),
    }


# ── KYC Beneficial Ownership Registry ────────────────────────────────────────
import json as _json
import os as _os

def _load_kyc_ownership() -> dict:
    """Load the KYC beneficial ownership registry from file."""
    path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), 'kyc_ownership.json')
    try:
        with open(path) as f:
            return _json.load(f)
    except Exception:
        return {}

_KYC_OWNERSHIP: dict = {}

def _get_ownership(entity_name: str) -> dict:
    """Look up ownership chain for an entity. Lazy-loads registry on first call."""
    global _KYC_OWNERSHIP
    if not _KYC_OWNERSHIP:
        _KYC_OWNERSHIP = _load_kyc_ownership()
    # Try exact match first
    if entity_name in _KYC_OWNERSHIP:
        return _KYC_OWNERSHIP[entity_name]
    # Try case-insensitive match
    name_lower = entity_name.lower()
    for key, val in _KYC_OWNERSHIP.items():
        if key.lower() == name_lower:
            return val
    # Try normalised match (strip LLC/Ltd/Corp suffixes)
    norm = _normalize(entity_name)
    for key, val in _KYC_OWNERSHIP.items():
        if _normalize(key) == norm:
            return val
    return {}


def screen_entity_with_ownership(
    name: str,
    country: str = None,
    entity_type: str = None,
    max_depth: int = 4,
) -> dict:
    """
    Layer 2 sanctions screening: screens the entity AND walks its KYC
    beneficial ownership chain, screening every owner up to max_depth hops.

    Returns the standard screen_entity result enriched with:
    - ownership_chain_screened: list of results for each owner
    - beneficial_owner_hit: True if any owner in the chain is a SDN match
    - hit_layer: which ownership layer triggered the hit (1=direct, 2+=indirect)
    - composite_risk: escalated to 'critical' if any layer hits
    """
    # ── Layer 1: screen the direct entity ────────────────────────────────────
    direct_result = screen_entity(name, country=country, entity_type=entity_type)

    # ── Layer 2+: walk the KYC ownership chain ───────────────────────────────
    ownership_data  = _get_ownership(name)
    chain           = ownership_data.get('ownership_chain', [])
    chain_results   = []
    beneficial_hit  = False
    hit_layer       = None
    hit_owner       = None

    for layer_rec in chain:
        layer_n      = layer_rec.get('layer', 0)
        owner_name   = layer_rec.get('owner_name', '')
        owner_country= layer_rec.get('owner_country', '')
        owner_type   = layer_rec.get('owner_type', 'Corporate')
        shell_flag   = layer_rec.get('shell_flag', False)
        is_ubo       = layer_rec.get('is_ubo', False)

        if not owner_name or layer_n > max_depth:
            continue

        owner_result = screen_entity(owner_name, country=owner_country,
                                     entity_type=owner_type.lower())
        chain_results.append({
            "layer":         layer_n,
            "owner_name":    owner_name,
            "owner_type":    owner_type,
            "owner_country": owner_country,
            "ownership_pct": layer_rec.get('ownership_pct', 0),
            "is_ubo":        is_ubo,
            "shell_flag":    shell_flag,
            "screen_status": owner_result['status'],
            "screen_risk":   owner_result['risk_level'],
            "matches":       owner_result['matches'][:2],
            "confirmed_hits":owner_result['confirmed_hits'],
            "potential_matches": owner_result['potential_matches'],
            "notes":         layer_rec.get('notes', ''),
        })

        if owner_result['status'] in ('HIT', 'POTENTIAL_MATCH') and not beneficial_hit:
            beneficial_hit = True
            hit_layer      = layer_n
            hit_owner      = owner_name

    # ── Assemble composite result ─────────────────────────────────────────────
    # Escalate risk if any ownership layer hits
    composite_risk = direct_result['risk_level']
    if beneficial_hit:
        composite_risk = 'critical'

    # Build ownership summary for the response
    ubo_name    = ownership_data.get('ubo_name', 'Unknown')
    ubo_country = ownership_data.get('ubo_country', 'Unknown')
    chain_depth = ownership_data.get('chain_depth', 0)
    has_offshore= ownership_data.get('has_offshore', False)
    shell_flag  = ownership_data.get('shell_flag', False)

    # Determine final status
    if direct_result['status'] == 'HIT':
        final_status = 'HIT'
        hit_description = f"Direct SDN match on '{name}'."
    elif beneficial_hit and chain_results:
        hit_rec = next((r for r in chain_results if r['layer'] == hit_layer), None)
        if hit_rec and hit_rec['confirmed_hits'] > 0:
            final_status = 'BENEFICIAL_OWNER_HIT'
            hit_description = (
                f"Direct entity CLEAR but beneficial owner '{hit_owner}' "
                f"at ownership layer {hit_layer} is a confirmed SDN match. "
                f"Wire must be blocked under OFAC regulations."
            )
        else:
            final_status = 'POTENTIAL_BENEFICIAL_OWNER_MATCH'
            hit_description = (
                f"Direct entity CLEAR but potential SDN match on owner "
                f"'{hit_owner}' at layer {hit_layer}. Requires enhanced review."
            )
        composite_risk = 'critical'
    elif direct_result['status'] in ('POTENTIAL_MATCH', 'WEAK_MATCH'):
        final_status = direct_result['status']
        hit_description = f"Potential name match on direct entity. Requires review."
    elif chain_depth > 0 and has_offshore:
        final_status = direct_result['status']
        hit_description = f"Entity CLEAR but ownership structure includes offshore jurisdictions. Enhanced due diligence recommended."
        if composite_risk == 'low':
            composite_risk = 'elevated'
    else:
        final_status = direct_result['status']
        hit_description = direct_result.get('action_required', False) and "Requires action." or "No matches found."

    return {
        **direct_result,
        "status":           final_status,
        "risk_level":       composite_risk,
        "hit_description":  hit_description,
        "direct_status":    direct_result['status'],
        "beneficial_owner_hit":   beneficial_hit,
        "hit_layer":        hit_layer,
        "hit_owner":        hit_owner,
        "ownership_chain_screened": chain_results,
        "ubo_name":         ubo_name,
        "ubo_country":      ubo_country,
        "chain_depth":      chain_depth,
        "has_offshore_owners": has_offshore,
        "shell_structure":  shell_flag,
        "action_required":  final_status in ('HIT', 'BENEFICIAL_OWNER_HIT',
                                              'POTENTIAL_BENEFICIAL_OWNER_MATCH',
                                              'POTENTIAL_MATCH'),
    }


def batch_screen(entities: list) -> list:
    return [screen_entity(e.get("name",""), e.get("country"), e.get("type")) for e in entities]


def get_sdn_stats() -> dict:
    programs, countries = {}, {}
    ofac_count = sum(1 for e in SDN_LIST if not e["id"].startswith("UN-"))
    un_count   = sum(1 for e in SDN_LIST if e["id"].startswith("UN-"))
    for e in SDN_LIST:
        for p in e.get("program", []):
            programs[p] = programs.get(p, 0) + 1
        c = e.get("country", "") or "Unknown"
        countries[c] = countries.get(c, 0) + 1
    top_programs  = sorted(programs.items(),  key=lambda x: -x[1])[:20]
    top_countries = sorted(countries.items(), key=lambda x: -x[1])[:10]
    un_programs = {}
    for e in SDN_LIST:
        if e["id"].startswith("UN-"):
            for p in e.get("program", []):
                clean_p = p.replace("UN-", "")
                un_programs[clean_p] = un_programs.get(clean_p, 0) + 1
    return {
        "total_entries":   len(SDN_LIST),
        "individuals":     sum(1 for e in SDN_LIST if e["type"] == "individual"),
        "entities":        sum(1 for e in SDN_LIST if e["type"] == "entity"),
        "ofac_entries":    ofac_count,
        "un_entries":      un_count,
        "programs_covered":len(programs),
        "top_programs":    top_programs,
        "top_countries":   top_countries,
        "un_programs":     sorted(un_programs.items(), key=lambda x: -x[1]),
        "lists_covered":   ["OFAC SDN", "UN Security Council Consolidated List"],
    }, {}
    for e in SDN_LIST:
        for p in e.get("program", []):
            programs[p] = programs.get(p,0)+1
        c = e.get("country","Unknown")
        countries[c] = countries.get(c,0)+1
    return {
        "total_entries":    len(SDN_LIST),
        "individuals":      sum(1 for e in SDN_LIST if e["type"]=="individual"),
        "entities":         sum(1 for e in SDN_LIST if e["type"]=="entity"),
        "programs_covered": len(programs),
        "top_programs":     sorted(programs.items(), key=lambda x:-x[1])[:10],
        "countries_covered":len(countries),
        "last_updated":     "OFAC SDN Apr 3 2026 (sdn_advanced.xml)",
        "high_risk_jurisdictions": len(HIGH_RISK_JURISDICTIONS),
    }
